    def test_ownership_every_failure_releases_completed_and_current_sinks(failure, base_exception):
        parts = [("upload", "first.bin", b"first"), ("upload", "second.bin", b"Q" * 31), ("last", None, b"done")]
        body = ownership_message(parts)
